epochs=dict(finalSource=ref(out/'final-source.json'),unchangedDuringFinalVerification=True,exploratory=[dict(label='first new-consumer exploratory epoch',counts=counts(out/'exploratory.xml'),note='284 passed including 15 existing route positives; pre-final source, no complete frozen source inventory captured for this first exploratory epoch. Superseded by final combined verification.',junit=ref(out/'exploratory.xml')),dict(label='affected pre-final epoch',counts=counts(out/'affected.xml'),source=ref(out/'affected-source.json'),note='550 passed, two fixture/schema failures. Equal B=C positive needed updated queue/query captures; at-B observation arriving after queued work needed a general queue inventory schema. Neither negative condition was weakened.',junit=ref(out/'affected.xml')),dict(label='corrected focused epoch',counts=counts(out/'affected-corrected.xml'),note='10 positives/identity controls pass after fixture/schema corrections; final source also adds complete retained-history identity admission and local query-source attribution.',junit=ref(out/'affected-corrected.xml'))],mutations=dict(runs=40,demonstratedGuards=39,targetedFailures=81,setupErrors=0,insensitive=[r['name'] for r in mutations if r['tests']['failures']==0],disposition='The redundant named-internal-metadata summary comparison survived removal because independent named-field mapping and case checks still rejected its malformed input. Removing the actual internal mapping guard failed all five corresponding controls. The insensitive probe is retained and is not claimed as demonstrated. All mutations used the same frozen final source. Earlier iteration mutations remain historical.'))
(out/'source-epoch-disposition.json').write_text(json.dumps(epochs,indent=2)+'\n')
for name in ('retain-native','final-evidence'):
 p=Path('/tmp/epic16-r8-'+name+'.py');shutil.copyfile(p,out/'verification-scripts'/p.name)
r=subprocess.run(['git','diff','--check'],capture_output=True);assert r.returncode==0,(r.stdout,r.stderr)
(out/'handoff-diff-check.stdout.txt').write_bytes(r.stdout);(out/'handoff-diff-check.stderr.txt').write_bytes(r.stderr)
artifacts=[ref(p) for p in sorted(out.rglob('*')) if p.is_file()]
